#ifndef NINJA_HASH_MAP_H_
#define NINJA_HASH_MAP_H_

#include <stdint.h>
#include <string.h>
#include <unordered_map>

#include "string_piece.h"

// MurmurHash2, 64-bit versions, by Austin Appleby
static inline unsigned int MurmurHash2(const void* key, size_t len) {
  static const unsigned int seed = 0xDECAFBAD;
  const unsigned int m = 0x5bd1e995;
  const int r = 24;
  unsigned int h = seed ^ len;
  const unsigned char* data = static_cast<const unsigned char*>(key);
  while (len >= 4) {
    unsigned int k;
    memcpy(&k, data, sizeof k);
    k *= m;
    k ^= k >> r;
    k *= m;
    h *= m;
    h ^= k;
    data += 4;
    len -= 4;
  }
  switch (len) {
  case 3: h ^= data[2] << 16;  // fallthrough
  case 2: h ^= data[1] << 8;   // fallthrough
  case 1: h ^= data[0];
    h *= m;
  };
  h ^= h >> 13;
  h *= m;
  h ^= h >> 15;
  return h;
}

struct ExternalStringHash {
  size_t operator()(StringPiece key) const {
    return MurmurHash2(key.str_, key.len_);
  }
};

struct ExternalStringEq {
  bool operator()(StringPiece a, StringPiece b) const { return a == b; }
};

template <typename V>
struct ExternalStringHashMap {
  typedef std::unordered_map<StringPiece, V, ExternalStringHash, ExternalStringEq> Type;
};

#endif
