void CanonicalizePath(std::string* path) {
  size_t len = path->size();
  if (len > 0) {
    CanonicalizePath(&(*path)[0], &len);
    path->resize(len);
  }
}

void CanonicalizePath(char* path, size_t* len) {
  if (*len == 0)
    return;

  char* start = path;
  char* dst = start;
  char* dst_start = dst;
  const char* src = start;
  const char* end = start + *len;

  bool absolute = false;
  if (*src == '/') {
    absolute = true;
    *dst++ = '/';
    ++src;
    dst_start = dst;
    // Collapse any further leading separators.
    while (src < end && *src == '/')
      ++src;
  }

  // Each entry is the start offset of a component relative to dst_start.
  std::vector<size_t> components;

  while (src < end) {
    const char* comp_end = src;
    while (comp_end < end && *comp_end != '/')
      ++comp_end;
    size_t comp_len = comp_end - src;
    if (comp_len == 0) {
      // empty component ("//")
    } else if (comp_len == 1 && src[0] == '.') {
      // "." component: skip.
    } else if (comp_len == 2 && src[0] == '.' && src[1] == '.') {
      // ".." component.
      bool can_pop = false;
      if (!components.empty()) {
        size_t last = components.back();
        size_t last_len = (dst - dst_start) - last;
        // Don't pop a ".." component.
        if (!(last_len == 2 && dst_start[last] == '.' &&
              dst_start[last + 1] == '.'))
          can_pop = true;
      }
      if (can_pop) {
        dst = dst_start + components.back();
        components.pop_back();
        if (dst > dst_start)
          --dst;  // remove separator before the popped component
      } else if (absolute && components.empty()) {
        // ".." at the root: keep it.
        if (dst > dst_start)
          *dst++ = '/';
        components.push_back(dst - dst_start);
        *dst++ = '.';
        *dst++ = '.';
      } else {
        if (dst > dst_start)
          *dst++ = '/';
        components.push_back(dst - dst_start);
        *dst++ = '.';
        *dst++ = '.';
      }
    } else {
      if (dst > dst_start)
        *dst++ = '/';
      components.push_back(dst - dst_start);
      memmove(dst, src, comp_len);
      dst += comp_len;
    }
    src = comp_end;
    if (src < end)
      ++src;  // skip the separator
  }

  if (dst == start) {
    *dst++ = '.';
  }
  *len = dst - start;
}

static inline bool IsKnownShellSafeCharacter(char ch) {
  if ('A' <= ch && ch <= 'Z') return true;
  if ('a' <= ch && ch <= 'z') return true;
  if ('0' <= ch && ch <= '9') return true;

  switch (ch) {
    case '_':
    case '+':
    case '-':
    case '.':
    case '/':
      return true;
    default:
      return false;
  }
}

static inline bool StringNeedsShellEscaping(const std::string& input) {
  for (size_t i = 0; i < input.size(); ++i) {
    if (!IsKnownShellSafeCharacter(input[i])) return true;
  }
  return false;
}

void GetShellEscapedString(const std::string& input, std::string* result) {
  if (!StringNeedsShellEscaping(input)) {
    result->append(input);
    return;
  }

  const char kQuote = '\'';
  const char kEscapeSequence[] = "'\\'";

  result->push_back(kQuote);

  std::string::const_iterator span_begin = input.begin();
  for (std::string::const_iterator it = input.begin(), end = input.end();
       it != end; ++it) {
    if (*it == kQuote) {
      result->append(span_begin, it);
      result->append(kEscapeSequence);
      span_begin = it;
    }
  }
  result->append(span_begin, input.end());
  result->push_back(kQuote);
}

int ReadFile(const std::string& path, std::string* contents, std::string* err) {
  FILE* f = fopen(path.c_str(), "rb");
  if (!f) {
    err->assign(strerror(errno));
    return -errno;
  }

  struct stat st;
  if (fstat(fileno(f), &st) < 0) {
    err->assign(strerror(errno));
    fclose(f);
    return -errno;
  }

  // +1 is for the resize in ManifestParser::Load
  contents->reserve(st.st_size + 1);

  char buf[64 << 10];
  size_t len;
  while (!feof(f) && (len = fread(buf, 1, sizeof(buf), f)) > 0) {
    contents->append(buf, len);
  }
  if (ferror(f)) {
    err->assign(strerror(errno));  // XXX errno?
    contents->clear();
    fclose(f);
    return -errno;
  }
  fclose(f);
  return 0;
}

void SetCloseOnExec(int fd) {
  int flags = fcntl(fd, F_GETFD);
  if (flags < 0) {
    perror("fcntl(F_GETFD)");
  } else {
    if (fcntl(fd, F_SETFD, flags | FD_CLOEXEC) < 0)
      perror("fcntl(F_SETFD)");
  }
}

int EditDistance(const StringPiece& s1, const StringPiece& s2,
                 bool allow_replacements, int max_edit_distance) {
  int m = s1.len_;
  int n = s2.len_;

  std::vector<int> row(n + 1);
  for (int i = 1; i <= n; ++i)
    row[i] = i;

  for (int y = 1; y <= m; ++y) {
    row[0] = y;
    int best_this_row = row[0];

    int previous = y - 1;
    for (int x = 1; x <= n; ++x) {
      int old_row = row[x];
      if (allow_replacements) {
        row[x] = std::min(previous + (s1.str_[y - 1] == s2.str_[x - 1] ? 0 : 1),
                          std::min(row[x - 1], row[x]) + 1);
      } else {
        if (s1.str_[y - 1] == s2.str_[x - 1])
          row[x] = previous;
        else
          row[x] = std::min(row[x - 1], row[x]) + 1;
      }
      previous = old_row;
      best_this_row = std::min(best_this_row, row[x]);
    }

    if (max_edit_distance && best_this_row > max_edit_distance)
      return max_edit_distance + 1;
  }

  return row[n];
}

const char* SpellcheckStringV(const std::string& text,
                              const std::vector<const char*>& words) {
  const bool kAllowReplacements = true;
  const int kMaxValidEditDistance = 3;

  int min_distance = kMaxValidEditDistance + 1;
  const char* result = NULL;
  for (std::vector<const char*>::const_iterator i = words.begin();
       i != words.end(); ++i) {
    int distance = EditDistance(*i, text, kAllowReplacements,
                                kMaxValidEditDistance);
    if (distance < min_distance) {
      min_distance = distance;
      result = *i;
    }
  }
  return result;
}

const char* SpellcheckString(const char* text, ...) {
  // Note: This takes a const char* instead of a string& because using
  // va_start() with a reference parameter is undefined behavior.
  va_list ap;
  va_start(ap, text);
  std::vector<const char*> words;
  const char* word;
  while ((word = va_arg(ap, const char*)))
    words.push_back(word);
  va_end(ap);
  return SpellcheckStringV(text, words);
}

bool islatinalpha(int c) {
  // isalpha() is locale-dependent.
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

std::string StripAnsiEscapeCodes(const std::string& in) {
  std::string stripped;
  stripped.reserve(in.size());

  for (size_t i = 0; i < in.size(); ++i) {
    if (in[i] != '\33') {
      // Not an escape code.
      stripped.push_back(in[i]);
      continue;
    }

    // Only strip CSIs for now.
    if (i + 1 >= in.size()) break;
    if (in[i + 1] != '[') continue;  // Not a CSI.
    i += 2;

    // Skip everything up to and including the next [a-zA-Z].
    while (i < in.size() && !islatinalpha(in[i]))
      ++i;
  }
  return stripped;
}

static int CalculateProcessorCountFromCgroup() {
  // cgroup v2: /sys/fs/cgroup/cpu.max contains "$MAX $PERIOD" or "max $PERIOD".
  std::ifstream cgroup("/sys/fs/cgroup/cpu.max");
  if (!cgroup)
    return 0;
  std::string quota_str, period_str;
  cgroup >> quota_str >> period_str;
  if (quota_str.empty() || period_str.empty() || quota_str == "max")
    return 0;
  char* end;
  long quota = strtol(quota_str.c_str(), &end, 10);
  if (*end != 0 || quota <= 0)
    return 0;
  long period = strtol(period_str.c_str(), &end, 10);
  if (*end != 0 || period <= 0)
    return 0;
  // Round up.
  long cpus = (quota + period - 1) / period;
  if (cpus <= 0)
    return 0;
  return static_cast<int>(cpus);
}

int GetProcessorCount() {
  int cgroup_count = CalculateProcessorCountFromCgroup();
  int sched_count = 0;
  cpu_set_t set;
  if (sched_getaffinity(getpid(), sizeof(set), &set) == 0) {
    sched_count = CPU_COUNT(&set);
  }
  if (sched_count <= 0)
    sched_count = sysconf(_SC_NPROCESSORS_ONLN);
  if (cgroup_count > 0 && cgroup_count < sched_count)
    return cgroup_count;
  return sched_count;
}

double GetLoadAverage() {
