  size_t len = path->size();
  if (len > 0) {
    CanonicalizePath(&(*path)[0], &len);
    path->resize(len);
  }
}

void CanonicalizePath(char* path, size_t* len) {
  if (*len == 0)
    return;

  char* start = path;
  char* dst = start;
  char* dst_start = dst;
  const char* src = start;
  const char* end = start + *len;

  bool absolute = false;
  if (*src == '/') {
    absolute = true;
    *dst++ = '/';
    ++src;
    dst_start = dst;
    // Collapse any further leading separators.
    while (src < end && *src == '/')
      ++src;
  }

  // Each entry is the start offset of a component relative to dst_start.
  std::vector<size_t> components;

  while (src < end) {
    const char* comp_end = src;
    while (comp_end < end && *comp_end != '/')
      ++comp_end;
    size_t comp_len = comp_end - src;
    if (comp_len == 0) {
      // empty component ("//")
    } else if (comp_len == 1 && src[0] == '.') {
      // "." component: skip.
    } else if (comp_len == 2 && src[0] == '.' && src[1] == '.') {
      // ".." component.
      bool can_pop = false;
      if (!components.empty()) {
        size_t last = components.back();
        size_t last_len = (dst - dst_start) - last;
        // Don't pop a ".." component.
        if (!(last_len == 2 && dst_start[last] == '.' &&
              dst_start[last + 1] == '.'))
          can_pop = true;
      }
      if (can_pop) {
        dst = dst_start + components.back();
        components.pop_back();
        if (dst > dst_start)
          --dst;  // remove separator before the popped component
      } else if (absolute && components.empty()) {
        // ".." at the root: keep it.
        if (dst > dst_start)
          *dst++ = '/';
        components.push_back(dst - dst_start);
        *dst++ = '.';
        *dst++ = '.';
      } else {
        if (dst > dst_start)
          *dst++ = '/';
        components.push_back(dst - dst_start);
        *dst++ = '.';
        *dst++ = '.';
      }
    } else {
      if (dst > dst_start)
        *dst++ = '/';
      components.push_back(dst - dst_start);
      memmove(dst, src, comp_len);
      dst += comp_len;
    }
    src = comp_end;
    if (src < end)
      ++src;  // skip the separator
  }

  if (dst == start) {
    *dst++ = '.';
  }
  *len = dst - start;
}

static inline bool IsKnownShellSafeCharacter(char ch) {
  if ('A' <= ch && ch <= 'Z') return true;
  if ('a' <= ch && ch <= 'z') return true;
  if ('0' <= ch && ch <= '9') return true;

  switch (ch) {
    case '_':
    case '+':
    case '-':
    case '.':
    case '/':
      return true;
    default:
      return false;
  }
}

static inline bool StringNeedsShellEscaping(const std::string& input) {
  for (size_t i = 0; i < input.size(); ++i) {
    if (!IsKnownShellSafeCharacter(input[i])) return true;
  }
  return false;
}

void GetShellEscapedString(const std::string& input, std::string* result) {
  if (!StringNeedsShellEscaping(input)) {
    result->append(input);
    return;
  }

  const char kQuote = '\'';
  const char kEscapeSequence[] = "'\\'";

  result->push_back(kQuote);

  std::string::const_iterator span_begin = input.begin();
  for (std::string::const_iterator it = input.begin(), end = input.end();
       it != end; ++it) {
    if (*it == kQuote) {
      result->append(span_begin, it);
      result->append(kEscapeSequence);
      span_begin = it;
    }
  }
  result->append(span_begin, input.end());
  result->push_back(kQuote);
}

int ReadFile(const std::string& path, std::string* contents, std::string* err) {
  FILE* f = fopen(path.c_str(), "rb");
  if (!f) {
    err->assign(strerror(errno));
    return -errno;
  }

  struct stat st;
  if (fstat(fileno(f), &st) < 0) {
    err->assign(strerror(errno));
    fclose(f);
    return -errno;
  }

  // +1 is for the resize in ManifestParser::Load
  contents->reserve(st.st_size + 1);

  char buf[64 << 10];
  size_t len;
  while (!feof(f) && (len = fread(buf, 1, sizeof(buf), f)) > 0) {
    contents->append(buf, len);
  }
  if (ferror(f)) {
    err->assign(strerror(errno));  // XXX errno?
    contents->clear();
    fclose(f);
    return -errno;
  }
  fclose(f);
  return 0;
}

