}

double GetLoadAverage() {
  double loadavg[3] = { 0.0f, 0.0f, 0.0f };
  if (getloadavg(loadavg, 3) < 0) {
    // Maybe we should return an error here or the availability of
    // getloadavg(3) should be checked when ninja is configured.
    return -0.0f;
  }
  return loadavg[0];
}

std::string ElideMiddle(const std::string& str, size_t width) {
  switch (width) {
      case 0: return "";
      case 1: return ".";
      case 2: return "..";
      case 3: return "...";
  }
  const int kMargin = 3;  // Space for "...".
  std::string result = str;
  if (result.size() > width) {
    size_t elide_size = (width - kMargin) / 2;
    result = result.substr(0, elide_size)
      + "..."
      + result.substr(result.size() - elide_size - ((width - kMargin) % 2), std::string::npos);
  }
  return result;
}

bool Truncate(const std::string& path, size_t size, std::string* err) {
  int success = truncate(path.c_str(), size);
  // Both truncate() and _chsize() return 0 on success and set errno and return
  // -1 on failure.
  if (success < 0) {
    *err = strerror(errno);
    return false;
  }
  return true;
}

// ---- rapidhash ----
static const uint64_t RAPID_SEED = 0xbdd89aa982704029ull;
static const uint64_t rapid_secret[3] = {0x2d358dccaa6c78a5ull, 0x8bb84b93962eacc9ull, 0x4b33a62ed433d4a3ull};
static inline void rapid_mum(uint64_t *A, uint64_t *B) {
  __uint128_t r = *A; r *= *B;
  *A = (uint64_t)r; *B = (uint64_t)(r >> 64);
}
static inline uint64_t rapid_mix(uint64_t A, uint64_t B) { rapid_mum(&A, &B); return A ^ B; }
static inline uint64_t rapid_read64(const uint8_t *p) { uint64_t v; memcpy(&v, p, 8); return v; }
static inline uint64_t rapid_read32(const uint8_t *p) { uint32_t v; memcpy(&v, p, 4); return v; }
static inline uint64_t rapid_readSmall(const uint8_t *p, size_t k) {
  return (((uint64_t)p[0]) << 56) | (((uint64_t)p[k >> 1]) << 32) | p[k - 1];
}
static inline uint64_t rapidhash_internal(const void *key, size_t len, uint64_t seed, const uint64_t *secret) {
  const uint8_t *p = (const uint8_t *)key;
  seed ^= rapid_mix(seed ^ secret[0], secret[1]) ^ len;
  uint64_t a, b;
  if (len <= 16) {
    if (len >= 4) {
      const uint8_t *plast = p + len - 4;
      a = (rapid_read32(p) << 32) | rapid_read32(plast);
      const uint64_t delta = ((len & 24) >> (len >> 3));
      b = ((rapid_read32(p + delta) << 32) | rapid_read32(plast - delta));
    } else if (len > 0) {
      a = rapid_readSmall(p, len);
      b = 0;
    } else
      a = b = 0;
  } else {
    size_t i = len;
    if (i > 48) {
      uint64_t see1 = seed, see2 = seed;
      while (i >= 96) {
        seed = rapid_mix(rapid_read64(p) ^ secret[0], rapid_read64(p + 8) ^ seed);
        see1 = rapid_mix(rapid_read64(p + 16) ^ secret[1], rapid_read64(p + 24) ^ see1);
        see2 = rapid_mix(rapid_read64(p + 32) ^ secret[2], rapid_read64(p + 40) ^ see2);
        seed = rapid_mix(rapid_read64(p + 48) ^ secret[0], rapid_read64(p + 56) ^ seed);
        see1 = rapid_mix(rapid_read64(p + 64) ^ secret[1], rapid_read64(p + 72) ^ see1);
        see2 = rapid_mix(rapid_read64(p + 80) ^ secret[2], rapid_read64(p + 88) ^ see2);
        p += 96; i -= 96;
      }
      if (i >= 48) {
        seed = rapid_mix(rapid_read64(p) ^ secret[0], rapid_read64(p + 8) ^ seed);
        see1 = rapid_mix(rapid_read64(p + 16) ^ secret[1], rapid_read64(p + 24) ^ see1);
        see2 = rapid_mix(rapid_read64(p + 32) ^ secret[2], rapid_read64(p + 40) ^ see2);
        p += 48; i -= 48;
      }
      seed ^= see1 ^ see2;
    }
    if (i > 16) {
      seed = rapid_mix(rapid_read64(p) ^ secret[2], rapid_read64(p + 8) ^ seed ^ secret[1]);
      if (i > 32)
        seed = rapid_mix(rapid_read64(p + 16) ^ secret[2], rapid_read64(p + 24) ^ seed);
    }
    a = rapid_read64(p + i - 16);
    b = rapid_read64(p + i - 8);
  }
  a ^= secret[1];
  b ^= seed;
  rapid_mum(&a, &b);
  return rapid_mix(a ^ secret[0] ^ len, b ^ secret[1]);
}

uint64_t HashCommand(StringPiece command) {
  return rapidhash_internal(command.str_, command.len_, RAPID_SEED, rapid_secret);
}

int64_t GetTimeMillis() {
  struct timespec ts;
  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (int64_t)ts.tv_sec * 1000 + ts.tv_nsec / 1000000;
}
