#include "lexer.h"

#include <stdio.h>

#include "eval_env.h"
#include "util.h"

static inline bool IsVarnameChar(char c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
         (c >= '0' && c <= '9') || c == '_' || c == '-' || c == '.';
}

static inline bool IsSimpleVarnameChar(char c) {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') ||
         (c >= '0' && c <= '9') || c == '_' || c == '-';
}

bool Lexer::Error(const std::string& message, std::string* err) {
  // Compute line/column.
  int line = 1;
  const char* line_start = input_.str_;
  for (const char* p = input_.str_; p < last_token_; ++p) {
    if (*p == '\n') {
      ++line;
      line_start = p + 1;
    }
  }
  int col = last_token_ ? (int)(last_token_ - line_start) : 0;

  char buf[1024];
  snprintf(buf, sizeof(buf), "%s:%d: ", filename_.AsString().c_str(), line);
  *err = buf;
  *err += message + "\n";

  // Add some context to the message.
  const int kTruncateColumn = 72;
  if (col > 0 && col < kTruncateColumn) {
    int len;
    bool truncated = true;
    for (len = 0; len < kTruncateColumn; ++len) {
      if (line_start[len] == 0 || line_start[len] == '\n') {
        truncated = false;
        break;
      }
    }
    *err += std::string(line_start, len);
    if (truncated)
      *err += "...";
    *err += "\n";
    *err += std::string(col, ' ');
    *err += "^ near here";
  }

  return false;
}

Lexer::Lexer(const char* input) : allow_newline_escape_(false) {
  Start("input", input);
}

void Lexer::Start(StringPiece filename, StringPiece input) {
  filename_ = filename;
  input_ = input;
  ofs_ = input_.str_;
  last_token_ = NULL;
}

const char* Lexer::TokenName(Token t) {
  switch (t) {
  case ERROR:    return "lexing error";
  case BUILD:    return "'build'";
  case COLON:    return "':'";
  case DEFAULT:  return "'default'";
  case EQUALS:   return "'='";
  case IDENT:    return "identifier";
  case INCLUDE:  return "'include'";
  case INDENT:   return "indent";
  case NEWLINE:  return "newline";
  case PIPE2:    return "'||'";
  case PIPE:     return "'|'";
  case PIPEAT:   return "'|@'";
  case POOL:     return "'pool'";
  case RULE:     return "'rule'";
  case SUBNINJA: return "'subninja'";
  case TEOF:     return "eof";
  }
  return NULL;  // not reached
}

const char* Lexer::TokenErrorHint(Token expected) {
  switch (expected) {
  case COLON:
    return " ($ also escapes ':')";
  default:
    return "";
  }
}

std::string Lexer::DescribeLastError() {
  if (last_token_) {
    switch (last_token_[0]) {
    case '\t':
      return "tabs are not allowed, use spaces";
    }
  }
  return "lexing error";
}

void Lexer::UnreadToken() {
  ofs_ = last_token_;
}

static bool MatchKeyword(const char* p, const char* kw) {
  size_t n = strlen(kw);
  if (strncmp(p, kw, n) != 0)
    return false;
  // Longest match: a keyword followed by a varname character is an identifier.
  return !IsVarnameChar(p[n]);
}

Lexer::Token Lexer::ReadToken() {
  const char* p = ofs_;
  const char* start;
  Lexer::Token token;
  for (;;) {
    start = p;
    // Leading spaces: could be a comment, newline, or indent.
    const char* q = p;
    while (*q == ' ')
      ++q;
    if (*q == '#') {
      // Comment: [ ]*"#"[^\000\n]*"\n"
      const char* r = q + 1;
      while (*r != 0 && *r != '\n')
        ++r;
      if (*r == '\n') {
        p = r + 1;
        continue;
      }
      // "#..." without newline: falls to the generic rules.
      if (q == p) {
        // '#' itself is not matched by anything else: error.
        p = q + 1;
        token = ERROR;
        break;
      }
      // spaces then '#' without newline: INDENT.
      p = q;
      token = INDENT;
      break;
    }
    if (*q == '\r' && q[1] == '\n') {
      p = q + 2;
      token = NEWLINE;
      break;
    }
    if (*q == '\n') {
      p = q + 1;
      token = NEWLINE;
      break;
    }
    if (q > p) {
      p = q;
      token = INDENT;
      break;
    }
    if (MatchKeyword(p, "build")) { p += 5; token = BUILD; break; }
    if (MatchKeyword(p, "pool")) { p += 4; token = POOL; break; }
    if (MatchKeyword(p, "rule")) { p += 4; token = RULE; break; }
    if (MatchKeyword(p, "default")) { p += 7; token = DEFAULT; break; }
    if (MatchKeyword(p, "include")) { p += 7; token = INCLUDE; break; }
    if (MatchKeyword(p, "subninja")) { p += 8; token = SUBNINJA; break; }
    if (*p == '=') { ++p; token = EQUALS; break; }
    if (*p == ':') { ++p; token = COLON; break; }
    if (*p == '|') {
      if (p[1] == '@') { p += 2; token = PIPEAT; break; }
      if (p[1] == '|') { p += 2; token = PIPE2; break; }
      ++p; token = PIPE; break;
    }
    if (IsVarnameChar(*p)) {
      while (IsVarnameChar(*p))
        ++p;
      token = IDENT;
      break;
    }
    if (*p == 0) { token = TEOF; break; }
    ++p;
    token = ERROR;
    break;
  }

  last_token_ = start;
  ofs_ = p;
  if (token != NEWLINE && token != TEOF)
    EatWhitespace();
  return token;
}

bool Lexer::PeekToken(Token token) {
  Token t = ReadToken();
  if (t == token)
    return true;
  UnreadToken();
  return false;
}

void Lexer::EatWhitespace() {
  const char* p = ofs_;
  for (;;) {
    ofs_ = p;
    if (*p == ' ') {
      while (*p == ' ')
        ++p;
      continue;
    }
    if (*p == '$' && p[1] == '\r' && p[2] == '\n') { p += 3; continue; }
    if (*p == '$' && p[1] == '\n') { p += 2; continue; }
    break;
  }
}

bool Lexer::ReadIdent(std::string* out) {
  const char* p = ofs_;
  const char* start = p;
  if (!IsVarnameChar(*p)) {
    last_token_ = start;
    return false;
  }
  while (IsVarnameChar(*p))
    ++p;
  out->assign(start, p - start);
  last_token_ = start;
  ofs_ = p;
  EatWhitespace();
  return true;
}

bool Lexer::ReadEvalString(EvalString* eval, bool path, std::string* err) {
  const char* p = ofs_;
  const char* start;
  for (;;) {
    start = p;
    char c = *p;
    if (c != '$' && c != ' ' && c != ':' && c != '\r' && c != '\n' &&
        c != '|' && c != 0) {
      // Plain text span: [^$ :\r\n|\000]+
      while (*p != '$' && *p != ' ' && *p != ':' && *p != '\r' &&
             *p != '\n' && *p != '|' && *p != 0)
        ++p;
      eval->AddText(StringPiece(start, p - start));
      continue;
    }
    if (c == '\r' && p[1] == '\n') {
      p += 2;
      if (path)
        p = start;
      break;
    }
    if (c == ' ' || c == ':' || c == '|' || c == '\n') {
      ++p;
      if (path) {
        p = start;
        break;
      } else {
        if (*start == '\n')
          break;
        eval->AddText(StringPiece(start, 1));
        continue;
      }
    }
    if (c == '$') {
      char d = p[1];
      if (d == '$') {
        p += 2;
        eval->AddText(StringPiece("$", 1));
        continue;
      }
      if (d == ' ') {
        p += 2;
        eval->AddText(StringPiece(" ", 1));
        continue;
      }
      if (d == '\r' && p[2] == '\n') {
        p += 3;
        while (*p == ' ')
          ++p;
        continue;
      }
      if (d == '\n') {
        p += 2;
        while (*p == ' ')
          ++p;
        continue;
      }
      if (d == '{') {
        const char* q = p + 2;
        if (IsVarnameChar(*q)) {
          while (IsVarnameChar(*q))
            ++q;
          if (*q == '}') {
            eval->AddSpecial(StringPiece(p + 2, q - (p + 2)));
            p = q + 1;
            continue;
          }
        }
        // Fall through to bad escape.
        last_token_ = start;
        return Error("bad $-escape (literal $ must be written as $$)", err);
      }
      if (IsSimpleVarnameChar(d)) {
        const char* q = p + 1;
        while (IsSimpleVarnameChar(*q))
          ++q;
        eval->AddSpecial(StringPiece(p + 1, q - (p + 1)));
        p = q;
        continue;
      }
      if (d == ':') {
        p += 2;
        eval->AddText(StringPiece(":", 1));
        continue;
      }
      if (d == '^') {
        if (!allow_newline_escape_) {
          return Error("using $^ escape requires specifying "
                       "'ninja_required_version' with version greater or "
                       "equal 1.14", err);
        }
        p += 2;
        eval->AddText(StringPiece("\n", 1));
        continue;
      }
      if (d == 0) {
        // "$" followed by EOF: the "$." rule can't match (no char), so this
        // is the nul rule for the next iteration.  re2c: "$." needs a char;
        // with NUL present, [^] would match '$' alone... but nul is matched
        // only when at start.  Treat as bad escape.
        last_token_ = start;
        return Error("bad $-escape (literal $ must be written as $$)", err);
      }
      // "$" followed by any other char.
      last_token_ = start;
      return Error("bad $-escape (literal $ must be written as $$)", err);
    }
    if (c == 0) {
      last_token_ = start;
      return Error("unexpected EOF", err);
    }
    // [^] : any other char (e.g. \r not followed by \n)
    last_token_ = start;
    return Error(DescribeLastError(), err);
  }
  last_token_ = start;
  ofs_ = p;
  if (path)
    EatWhitespace();
  // Non-path strings end in newlines, so there's no whitespace to eat.
  return true;
}
