/// A pool for delayed edges.
/// Pools are scoped to a State. Edges within a State will share Pools. A Pool
/// will keep a count of the total 'weight' of the currently scheduled edges. If
/// a Plan attempts to schedule an Edge which would cause the total weight to
/// exceed the depth of the Pool, the Pool will enqueue the Edge instead of
/// allowing the Plan to schedule it. The Pool will relinquish queued Edges when
/// the total scheduled weight diminishes enough (i.e. when a scheduled edge
/// completes).
struct Pool {
  Pool(const std::string& name, int depth)
    : name_(name), current_use_(0), depth_(depth), delayed_() {}

  // A depth of 0 is infinite
  bool is_valid() const { return depth_ >= 0; }
  int depth() const { return depth_; }
  const std::string& name() const { return name_; }
  int current_use() const { return current_use_; }

  /// true if the Pool might delay this edge
  bool ShouldDelayEdge() const { return depth_ != 0; }

  /// informs this Pool that the given edge is committed to be run.
  /// Pool will count this edge as using resources from this pool.
  void EdgeScheduled(const Edge& edge);

  /// informs this Pool that the given edge is no longer runnable, and should
  /// relinquish its resources back to the pool
  void EdgeFinished(const Edge& edge);

  /// adds the given edge to this Pool to be delayed.
  void DelayEdge(Edge* edge);

  /// Pool will add zero or more edges to the ready_queue
  void RetrieveReadyEdges(EdgePriorityQueue* ready_queue);

  /// Dump the Pool and its edges (useful for debugging).
  void Dump() const;

 private:
  std::string name_;

  /// |current_use_| is the total of the weights of the edges which are
  /// currently scheduled in the Plan (i.e. the edges in Plan::ready_).
  int current_use_;
  int depth_;

  typedef std::set<Edge*, EdgePriorityGreater> DelayedEdges;
  DelayedEdges delayed_;
};

/// An insertion-ordered hash map from path to Node*.
struct PathMap {
  typedef std::vector<std::pair<StringPiece, Node*> > Entries;
  typedef Entries::const_iterator const_iterator;
  typedef Entries::iterator iterator;

  Node* Lookup(StringPiece key) const {
    Index::const_iterator i = index_.find(key);
    if (i == index_.end())
      return NULL;
    return entries_[i->second].second;
  }
  /// Insert a node; the key must point to the node's path storage.
  void Insert(StringPiece key, Node* node) {
    index_[key] = entries_.size();
    entries_.push_back(std::make_pair(key, node));
  }

  const_iterator begin() const { return entries_.begin(); }
  const_iterator end() const { return entries_.end(); }
  iterator begin() { return entries_.begin(); }
  iterator end() { return entries_.end(); }
  size_t size() const { return entries_.size(); }
  /// Emulates the bucket count of the reference implementation.
  size_t bucket_count() const {
    size_t buckets = 4;
    while (entries_.size() * 5 > buckets * 4)
      buckets *= 2;
    return buckets;
  }

 private:
  typedef ExternalStringHashMap<size_t>::Type Index;
  Index index_;
  Entries entries_;
};

/// Global state (file status) for a single run.
struct State {
  static Pool kDefaultPool;
  static Pool kConsolePool;
  static const Rule kPhonyRule;

  State();

  void AddPool(Pool* pool);
