/// Store a log of every command ran for every build.
/// It has a few uses:
///
/// 1) (hashes of) command lines for existing output files, so we know
///    when we need to rebuild due to the command changing
/// 2) timing information, perhaps for generating reports
/// 3) restat information
struct BuildLog {
  BuildLog();
  ~BuildLog();

  /// Prepares writing to the log file without actually opening it - that will
  /// happen when/if it's needed
  bool OpenForWrite(const std::string& path, const BuildLogUser& user,
                    std::string* err);
  bool RecordCommand(Edge* edge, int start_time, int end_time,
                     TimeStamp mtime = 0);
  void Close();

  /// Load the on-disk log.
  LoadStatus Load(const std::string& path, std::string* err);

  struct LogEntry {
    std::string output;
    uint64_t command_hash;
    int start_time;
    int end_time;
    TimeStamp mtime;

    static uint64_t HashCommand(StringPiece command);

    // Used by tests.
    bool operator==(const LogEntry& o) {
      return output == o.output && command_hash == o.command_hash &&
          start_time == o.start_time && end_time == o.end_time &&
          mtime == o.mtime;
    }

    explicit LogEntry(const std::string& output);
    LogEntry(const std::string& output, uint64_t command_hash,
             int start_time, int end_time, TimeStamp mtime);
  };

  /// Lookup a previously-run command by its output path.
  LogEntry* LookupByOutput(const std::string& path);

  /// Serialize an entry into a log file.
  bool WriteEntry(FILE* f, const LogEntry& entry);

  /// Rewrite the known log entries, throwing away old data.
  bool Recompact(const std::string& path, const BuildLogUser& user,
                 std::string* err);

  /// Restat all outputs in the log
  bool Restat(StringPiece path, const DiskInterface& disk_interface,
              int output_count, char** outputs, std::string* err);

  /// Insertion-ordered map of output -> entry.
  struct Entries {
    typedef std::vector<LogEntry*> List;
    typedef List::const_iterator const_iterator;
    typedef List::iterator iterator;

    LogEntry* Lookup(StringPiece key) const {
      Index::const_iterator i = index_.find(key);
      if (i == index_.end())
        return NULL;
      return list_[i->second];
    }
    void Insert(LogEntry* entry) {
      index_[StringPiece(entry->output)] = list_.size();
      list_.push_back(entry);
    }
    const_iterator begin() const { return list_.begin(); }
    const_iterator end() const { return list_.end(); }
    iterator begin() { return list_.begin(); }
    iterator end() { return list_.end(); }
    size_t size() const { return list_.size(); }
    bool empty() const { return list_.empty(); }
    void clear() { index_.clear(); list_.clear(); }

   private:
    typedef ExternalStringHashMap<size_t>::Type Index;
    Index index_;
    List list_;
  };
  const Entries& entries() const { return entries_; }

 private:
  /// Should be called before using log_file_. When false is returned, errno
  /// will be set.
  bool OpenForWriteIfNeeded();

  Entries entries_;
  FILE* log_file_;
  std::string log_file_path_;
  bool needs_recompaction_;
};

#endif // NINJA_BUILD_LOG_H_
