#include "util.h"

#include <algorithm>
#include <string.h>

DepfileParser::DepfileParser(DepfileParserOptions options)
  : options_(options)
{
}

static inline bool IsPlainChar(unsigned char c) {
  // [a-zA-Z0-9+,/_:.~()}{%=@\x5B\x5D!\x80-\xFF-]
  if (c >= 'a' && c <= 'z') return true;
  if (c >= 'A' && c <= 'Z') return true;
  if (c >= '0' && c <= '9') return true;
  if (c >= 0x80) return true;
  switch (c) {
  case '+': case ',': case '/': case '_': case ':': case '.': case '~':
  case '(': case ')': case '}': case '{': case '%': case '=': case '@':
  case '[': case ']': case '!': case '-':
    return true;
  }
  return false;
}

// A note on backslashes in Makefiles, from reading the docs:
// Backslash-newline is the line continuation character.
// Backslash-# escapes a # (otherwise meaningful as a comment start).
// Backslash-% escapes a % (otherwise meaningful as a special).
// Finally, quoting the GNU manual, "Backslashes that are not in danger
// of quoting ‘%’ characters go unmolested."
// How do you end a line with a backslash?  The netbsd Make docs suggest
// reading the result of a shell command echoing a backslash!
//
// Rather than implement all of above, we follow what GCC/Clang produces:
// Backslashes escape a space or hash sign.
// When a space is preceded by 2N+1 backslashes, it is represents N backslashes
// followed by space.
// When a space is preceded by 2N backslashes, it represents 2N backslashes at
// the end of a filename.
// A hash sign is escaped by a single backslash. All other backslashes remain
// unchanged.
//
// If anyone actually has depfiles that rely on the more complicated
// behavior we can adjust this.
bool DepfileParser::Parse(std::string* content, std::string* err) {
  // in: current parser input point.
  // end: end of input.
  // parsing_targets: whether we are parsing targets or dependencies.
  char* in = &(*content)[0];
  char* end = in + content->size();
  bool have_target = false;
  bool parsing_targets = true;
  bool poisoned_input = false;
  while (in < end) {
    bool have_newline = false;
    // out: current output point (typically same as in, but can fall behind
    // as we de-escape backslashes).
    char* out = in;
    // filename: start of the current parsed filename.
    char* filename = out;
    for (;;) {
      // start: beginning of the current parsed span.
      const char* start = in;
      unsigned char c = (unsigned char)*in;

      if (c == '\\') {
        // Count the run of backslashes.
        const char* p = in;
        while (*p == '\\')
          ++p;
        size_t nbs = p - in;
        unsigned char next = (unsigned char)*p;
        if (next == ' ' && (nbs % 2 == 1)) {
          // 2N+1 backslashes plus space -> N backslashes plus space.
          in = const_cast<char*>(p) + 1;
          int n = nbs / 2;
          if (out < start)
            memset(out, '\\', n);
          out += n;
          *out++ = ' ';
          continue;
        }
        if (next == '#' && (nbs % 2 == 1)) {
          // 2N+1 backslashes plus # -> N backslashes plus #.
          in = const_cast<char*>(p) + 1;
          int n = nbs / 2;
          if (out < start)
            memset(out, '\\', n);
          out += n;
          *out++ = '#';
          continue;
        }
        if (next == ':' && (nbs % 2 == 1)) {
          // 2N+1 backslashes plus : -> N backslashes plus :.
          in = const_cast<char*>(p) + 1;
          int n = nbs / 2;
          if (out < start)
            memset(out, '\\', n);
          out += n;
          *out++ = ':';
          continue;
        }
        if (next == ' ' && (nbs % 2 == 0)) {
          // 2N backslashes plus space -> 2N backslashes, end of filename.
          in = const_cast<char*>(p) + 1;
          int len = (int)(in - start);
          if (out < start)
            memset(out, '\\', len - 1);
          out += len - 1;
          break;
        }
        if (nbs == 1 && (next == '\n' || (next == '\r' && p[1] == '\n'))) {
          // A line continuation ends the current file name.
          in = const_cast<char*>(p) + (next == '\r' ? 2 : 1);
          break;
        }
        if (next != 0 && next != '\r' && next != '\n') {
          // '\\'+ [^\000\r\n] : a span of plain text (backslashes kept).
          // Note: "\\\\\n" (2 backslashes + newline) matches this rule
          // with the second backslash as the trailing char.
          in = const_cast<char*>(p) + 1;
          int len = (int)(in - start);
          if (out < start)
            memmove(out, start, len);
          out += len;
          continue;
        }
        if (nbs >= 2) {
          // Backslashes followed by nul/newline: the rule '\\'+ [^\000\r\n]
          // matches nbs-1 backslashes with the last backslash as the char.
          in = const_cast<char*>(p);
          int len = (int)(in - start);
          if (out < start)
            memmove(out, start, len);
          out += len;
          continue;
        }
        // Single backslash followed by nul or stray '\r': swallow ([^]).
        ++in;
        break;
      }
      if (c == '$') {
        if (in[1] == '$') {
          // De-escape dollar character.
          in += 2;
          *out++ = '$';
          continue;
        }
        // Lone '$': swallowed by [^].
        ++in;
        break;
      }
      if (IsPlainChar(c)) {
        // Got a span of plain text.
        while (IsPlainChar((unsigned char)*in))
          ++in;
        int len = (int)(in - start);
        // Need to shift it over if we're overwriting backslashes.
        if (out < start)
          memmove(out, start, len);
        out += len;
        continue;
      }
      if (c == 0) {
        break;
      }
      if (c == '\n') {
        ++in;
        have_newline = true;
        break;
      }
      if (c == '\r' && in[1] == '\n') {
        in += 2;
        have_newline = true;
        break;
      }
      // For any other character (e.g. whitespace), swallow it here,
      // allowing the outer logic to loop around again.
      ++in;
      break;
    }

    int len = (int)(out - filename);
    const bool is_dependency = !parsing_targets;
    if (len > 0 && filename[len - 1] == ':') {
      len--;  // Strip off trailing colon, if any.
      parsing_targets = false;
      have_target = true;
    }

    if (len > 0) {
      StringPiece piece = StringPiece(filename, len);
      // If we've seen this as an input before, skip it.
      std::vector<StringPiece>::iterator pos = std::find(ins_.begin(), ins_.end(), piece);
      if (pos == ins_.end()) {
        if (is_dependency) {
          if (poisoned_input) {
            *err = "inputs may not also have inputs";
            return false;
          }
          // New input.
          ins_.push_back(piece);
        } else {
          // Check for a new output.
          if (std::find(outs_.begin(), outs_.end(), piece) == outs_.end())
            outs_.push_back(piece);
        }
      } else if (!is_dependency) {
        // We've passed an input on the left side; reject new inputs.
        poisoned_input = true;
      }
    }

    if (have_newline) {
      // A newline ends a rule so the next filename will be a new target.
      parsing_targets = true;
      poisoned_input = false;
    }
  }
  if (!have_target) {
    *err = "expected ':' in depfile";
    return false;
  }
  return true;
}
