#include "jobserver.h"

#include <errno.h>
#include <fcntl.h>
#include <string.h>
#include <sys/stat.h>
#include <unistd.h>

bool Jobserver::ParseMakeFlags(const std::string& makeflags, Config* config) {
  // Look for the last --jobserver-auth=VALUE or --jobserver-fds=VALUE.
  static const char* const kPrefixes[] = { "--jobserver-auth=",
                                           "--jobserver-fds=" };
  bool found = false;
  std::string value;
  size_t pos = 0;
  while (pos < makeflags.size()) {
    // Skip whitespace.
    while (pos < makeflags.size() && makeflags[pos] == ' ')
      ++pos;
    if (pos >= makeflags.size())
      break;
    size_t end = makeflags.find(' ', pos);
    if (end == std::string::npos)
      end = makeflags.size();
    std::string word = makeflags.substr(pos, end - pos);
    for (size_t i = 0; i < 2; ++i) {
      size_t len = strlen(kPrefixes[i]);
      if (word.size() >= len && word.compare(0, len, kPrefixes[i]) == 0) {
        value = word.substr(len);
        found = true;
      }
    }
    pos = end;
  }
  if (!found)
    return false;

  if (value.compare(0, 5, "fifo:") == 0) {
    config->mode = Config::kModePosixFifo;
    config->path = value.substr(5);
  } else if (value.find(',') != std::string::npos) {
    config->mode = Config::kModePipe;
  } else {
    config->mode = Config::kModeWin32Semaphore;
    config->path = value;
  }
  return true;
}

Jobserver::Client::~Client() {
  if (read_fd_ >= 0)
    close(read_fd_);
  if (write_fd_ >= 0)
    close(write_fd_);
}

Jobserver::Client* Jobserver::Client::Create(const Config& config,
                                             std::string* error) {
  if (config.path.empty()) {
    *error = "Empty fifo path";
    return NULL;
  }
  int read_fd = open(config.path.c_str(), O_RDONLY | O_NONBLOCK | O_CLOEXEC);
  if (read_fd < 0) {
    *error = std::string("Error opening fifo for reading: ") + strerror(errno);
    return NULL;
  }
  struct stat st;
  if (fstat(read_fd, &st) < 0 || !S_ISFIFO(st.st_mode)) {
    close(read_fd);
    *error = "Not a fifo path: " + config.path;
    return NULL;
  }
  int write_fd = open(config.path.c_str(), O_WRONLY | O_CLOEXEC);
  if (write_fd < 0) {
    close(read_fd);
    *error = std::string("Error opening fifo for writing: ") + strerror(errno);
    return NULL;
  }
  Client* client = new Client();
  client->read_fd_ = read_fd;
  client->write_fd_ = write_fd;
  return client;
}

Jobserver::Slot Jobserver::Client::TryAcquire() {
  Slot slot;
  if (!implicit_used_) {
    implicit_used_ = true;
    slot.valid = true;
    slot.implicit = true;
    return slot;
  }
  unsigned char c;
  for (;;) {
    ssize_t n = read(read_fd_, &c, 1);
    if (n == 1) {
      slot.valid = true;
      slot.token = c;
      return slot;
    }
    if (n < 0 && errno == EINTR)
      continue;
    return slot;
  }
}

void Jobserver::Client::Release(const Slot& slot) {
  if (!slot.valid)
    return;
  if (slot.implicit) {
    implicit_used_ = false;
    return;
  }
  unsigned char c = slot.token;
  for (;;) {
    ssize_t n = write(write_fd_, &c, 1);
    if (n == 1)
      return;
    if (n < 0 && errno == EINTR)
      continue;
    return;
  }
}
