#!/usr/bin/env python3
"""Inline a Python script into a C++ header as a NUL-terminated char array."""
import sys

def main():
    if len(sys.argv) != 3:
        print("usage: inline.py VARNAME INPUT > OUTPUT", file=sys.stderr)
        return 1
    varname, path = sys.argv[1], sys.argv[2]
    data = open(path, 'rb').read()
    print('// Generated by inline.py; do not edit.')
    print('const char %s[] = {' % varname)
    line = []
    for i, b in enumerate(data):
        line.append('%d,' % b)
        if len(line) == 20:
            print(' '.join(line))
            line = []
    line.append('0')
    print(' '.join(line))
    print('};')
    return 0

if __name__ == '__main__':
