enum PrintCommandMode { PCM_Single, PCM_All };
void PrintCommands(Edge* edge, EdgeSet* seen, PrintCommandMode mode) {
  if (!edge)
    return;
  if (!seen->insert(edge).second)
    return;

  if (mode == PCM_All) {
    for (std::vector<Node*>::iterator in = edge->inputs_.begin();
         in != edge->inputs_.end(); ++in)
      PrintCommands((*in)->in_edge(), seen, mode);
  }

  if (!edge->is_phony())
    puts(edge->EvaluateCommand().c_str());
}

int NinjaMain::ToolCommands(const Options* options, int argc, char* argv[]) {
  // The commands tool uses getopt, and expects argv[0] to contain the name of
  // the tool, i.e. "commands".
  ++argc;
  --argv;

  PrintCommandMode mode = PCM_All;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hs"))) != -1) {
    switch (opt) {
    case 's':
      mode = PCM_Single;
      break;
    case 'h':
    default:
      printf("usage: ninja -t commands [options] [targets]\n"
"\n"
"options:\n"
"  -s     only print the final command to build [target], not the whole chain\n"
             );
    return 1;
    }
  }
  argv += optind;
  argc -= optind;

  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }

  EdgeSet seen;
  for (std::vector<Node*>::iterator in = nodes.begin(); in != nodes.end(); ++in)
    PrintCommands((*in)->in_edge(), &seen, mode);

  return 0;
}

/// Collects the transitive set of inputs of a set of nodes, in dependency
/// order.
struct InputsCollector {
  void VisitNode(const Node* node) {
    const Edge* edge = node->in_edge();
    if (!edge)
      return;  // A source file.
    if (!visited_edges_.insert(edge).second)
      return;  // Already visited.
    for (const Node* input : edge->inputs_) {
      if (visited_nodes_.insert(input).second) {
        VisitNode(input);
        inputs_.push_back(input);
      }
    }
  }

  std::vector<std::string> GetInputsAsStrings(bool shell_escape) const {
    std::vector<std::string> result;
    result.reserve(inputs_.size());
    for (const Node* input : inputs_) {
      if (shell_escape) {
        std::string unescaped = input->PathDecanonicalized();
        std::string escaped;
        GetShellEscapedString(unescaped, &escaped);
        result.push_back(std::move(escaped));
      } else {
        result.push_back(input->PathDecanonicalized());
      }
    }
    return result;
  }

  std::vector<const Node*> inputs_;
  std::set<const Node*> visited_nodes_;
  std::set<const Edge*> visited_edges_;
};

int NinjaMain::ToolInputs(const Options* options, int argc, char* argv[]) {
  // The inputs tool uses getopt_long, and expects argv[0] to contain the name
  // of the tool, i.e. "inputs".
  argc++;
  argv--;

  bool print0 = false;
  bool shell_escape = true;
  bool dependency_order = false;

  optind = 1;
  int opt;
  const option kLongOptions[] = { { "help", no_argument, NULL, 'h' },
                                  { "no-shell-escape", no_argument, NULL, 'E' },
                                  { "print0", no_argument, NULL, '0' },
                                  { "dependency-order", no_argument, NULL,
                                    'd' },
                                  { NULL, 0, NULL, 0 } };
  while ((opt = getopt_long(argc, argv, "d0Eh", kLongOptions, NULL)) != -1) {
    switch (opt) {
    case 'd':
      dependency_order = true;
      break;
    case '0':
      print0 = true;
      break;
    case 'E':
      shell_escape = false;
      break;
    case 'h':
    default:
      // clang-format off
      printf(
"Usage '-t inputs [options] [targets]\n"
"\n"
"List all inputs used for a set of targets, sorted in dependency order.\n"
"Note that by default, results are shell escaped, and sorted alphabetically,\n"
"and never include validation target paths.\n\n"
"Options:\n"
"  -h, --help          Print this message.\n"
"  -0, --print0            Use \\0, instead of \\n as a line terminator.\n"
"  -E, --no-shell-escape   Do not shell escape the result.\n"
"  -d, --dependency-order  Sort results by dependency order.\n"
      );
      // clang-format on
      return 1;
    }
  }
  argv += optind;
  argc -= optind;

  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }

  InputsCollector collector;
  for (const Node* node : nodes)
    collector.VisitNode(node);

  std::vector<std::string> inputs = collector.GetInputsAsStrings(shell_escape);
  if (!dependency_order)
    std::sort(inputs.begin(), inputs.end());

  if (print0) {
    for (const std::string& input : inputs) {
      fwrite(input.c_str(), input.size(), 1, stdout);
      fputc('\0', stdout);
    }
    fflush(stdout);
  } else {
    for (const std::string& input : inputs)
      puts(input.c_str());
  }
  return 0;
}

int NinjaMain::ToolMultiInputs(const Options* options, int argc, char* argv[]) {
  // The inputs tool uses getopt_long, and expects argv[0] to contain the name
  // of the tool, i.e. "multi-inputs".
  argc++;
  argv--;

  bool print0 = false;
  const char* delimiter = "\t";

  optind = 1;
  int opt;
  const option kLongOptions[] = { { "help", no_argument, NULL, 'h' },
                                  { "delimiter", required_argument, NULL, 'd' },
                                  { "print0", no_argument, NULL, '0' },
                                  { NULL, 0, NULL, 0 } };
  while ((opt = getopt_long(argc, argv, "d:0h", kLongOptions, NULL)) != -1) {
    switch (opt) {
    case 'd':
      delimiter = optarg;
      break;
    case '0':
      print0 = true;
      break;
    case 'h':
    default:
      // clang-format off
      printf(
"Usage '-t multi-inputs [options] [targets]\n"
"\n"
"Print one or more sets of inputs required to build targets, sorted in dependency order.\n"
"The tool works like inputs tool but with addition of the target for each line.\n"
"The output will be a series of lines with the following elements:\n"
"<target> <delimiter> <input> <terminator>\n"
"Note that a given input may appear for several targets if it is used by more than one targets.\n"
"Options:\n"
"  -h, --help                   Print this message.\n"
"  -d  --delimiter=DELIM        Use DELIM instead of TAB for field delimiter.\n"
"  -0, --print0                 Use \\0, instead of \\n as a line terminator.\n"
      );
      // clang-format on
      return 1;
    }
  }
  argv += optind;
  argc -= optind;

  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Error("%s", err.c_str());
    return 1;
  }

  char terminator = print0 ? '\0' : '\n';

  for (const Node* node : nodes) {
    InputsCollector collector;
    collector.VisitNode(node);
    std::vector<std::string> inputs = collector.GetInputsAsStrings(false);
    for (const std::string& input : inputs) {
      printf("%s%s%s", node->path().c_str(), delimiter, input.c_str());
      fputc(terminator, stdout);
    }
  }
  fflush(stdout);
  return 0;
}

int NinjaMain::ToolClean(const Options* options, int argc, char* argv[]) {
  // The clean tool uses getopt, and expects argv[0] to contain the name of
  // the tool, i.e. "clean".
  argc++;
  argv--;

  bool generator = false;
  bool clean_rules = false;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hgr"))) != -1) {
    switch (opt) {
    case 'g':
      generator = true;
      break;
    case 'r':
      clean_rules = true;
      break;
    case 'h':
    default:
      printf("usage: ninja -t clean [options] [targets]\n"
"\n"
"options:\n"
"  -g     also clean files marked as ninja generator output\n"
"  -r     interpret targets as a list of rules to clean instead\n"
             );
    return 1;
    }
  }
  argv += optind;
  argc -= optind;

  if (clean_rules && argc == 0) {
    Error("expected a rule to clean");
    return 1;
  }

  Cleaner cleaner(&state_, config_, &disk_interface_);
  if (argc >= 1) {
    if (clean_rules)
      return cleaner.CleanRules(argc, argv);
    else
      return cleaner.CleanTargets(argc, argv);
  } else {
    return cleaner.CleanAll(generator);
  }
}

