enum EvaluateCommandMode {
  ECM_NORMAL,
  ECM_EXPAND_RSPFILE
};
std::string EvaluateCommandWithRspfile(const Edge* edge,
                                       const EvaluateCommandMode mode) {
  std::string command = edge->EvaluateCommand();
  if (mode == ECM_NORMAL)
    return command;

  std::string rspfile = edge->GetUnescapedRspfile();
  if (rspfile.empty())
    return command;

  size_t index = command.find(rspfile);
  if (index == 0 || index == std::string::npos || command[index - 1] != '@')
    return command;

  std::string rspfile_content = edge->GetBinding("rspfile_content");
  size_t newline_index = 0;
  while ((newline_index = rspfile_content.find('\n', newline_index)) !=
         std::string::npos) {
    rspfile_content.replace(newline_index, 1, 1, ' ');
    ++newline_index;
  }
  command.replace(index - 1, rspfile.length() + 1, rspfile_content);
  return command;
}

void printCompdb(const char* const directory, const Edge* const edge,
                 const Node* const input, const EvaluateCommandMode eval_mode) {
  printf("\n  {\n    \"directory\": \"");
  fputs(EncodeJSONString(directory).c_str(), stdout);
  printf("\",\n    \"command\": \"");
  fputs(EncodeJSONString(EvaluateCommandWithRspfile(edge, eval_mode)).c_str(), stdout);
  printf("\",\n    \"file\": \"");
  fputs(EncodeJSONString(input->path()).c_str(), stdout);
  printf("\",\n    \"output\": \"");
  fputs(EncodeJSONString(edge->outputs_[0]->path()).c_str(), stdout);
  printf("\"\n  }");
}

static bool GetCwd(std::vector<char>* cwd) {
  char* success = NULL;
  do {
    cwd->resize(cwd->size() + 1024);
    errno = 0;
    success = getcwd(&(*cwd)[0], cwd->size());
  } while (!success && errno == ERANGE);
  if (!success) {
    Error("cannot determine working directory: %s", strerror(errno));
    return false;
  }
  return true;
}

int NinjaMain::ToolCompilationDatabase(const Options* options, int argc,
                                       char* argv[]) {
  // The compdb tool uses getopt, and expects argv[0] to contain the name of
  // the tool, i.e. "compdb".
  argc++;
  argv--;

  EvaluateCommandMode eval_mode = ECM_NORMAL;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hx"))) != -1) {
    switch(opt) {
      case 'x':
        eval_mode = ECM_EXPAND_RSPFILE;
        break;

      case 'h':
      default:
        printf(
            "usage: ninja -t compdb [options] [rules]\n"
            "\n"
            "options:\n"
            "  -x     expand @rspfile style response file invocations\n"
            );
        return 1;
    }
  }
  argv += optind;
  argc -= optind;

  bool first = true;
  std::vector<char> cwd;
  if (!GetCwd(&cwd))
    return 1;

  putchar('[');
  for (std::vector<Edge*>::iterator e = state_.edges_.begin();
       e != state_.edges_.end(); ++e) {
    if ((*e)->inputs_.empty())
      continue;
    bool matches = (argc == 0);
    for (int i = 0; !matches && i != argc; ++i) {
      if ((*e)->rule_->name() == argv[i])
        matches = true;
    }
    if (!matches)
      continue;
    for (std::vector<Node*>::iterator in = (*e)->inputs_.begin();
         in != (*e)->inputs_.end(); ++in) {
      if (!first) {
        putchar(',');
      }
      printCompdb(&cwd[0], *e, *in, eval_mode);
      first = false;
    }
  }

  puts("\n]");
  return 0;
}

static void CollectCompdbEdges(Edge* edge, std::set<Edge*>* seen,
                               std::vector<Edge*>* result) {
  if (!edge)
    return;
  if (!seen->insert(edge).second)
    return;
  for (std::vector<Node*>::iterator in = edge->inputs_.begin();
       in != edge->inputs_.end(); ++in)
    CollectCompdbEdges((*in)->in_edge(), seen, result);
  if (!edge->is_phony())
    result->push_back(edge);
}

int NinjaMain::ToolCompilationDatabaseForTargets(const Options* options,
                                                 int argc, char* argv[]) {
  // The compdb-targets tool uses getopt, and expects argv[0] to contain the
  // name of the tool, i.e. "compdb-targets".
  argc++;
  argv--;

  EvaluateCommandMode eval_mode = ECM_NORMAL;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("hx"))) != -1) {
    switch (opt) {
    case 'x':
      eval_mode = ECM_EXPAND_RSPFILE;
      break;

    case 'h':
    default:
      printf("usage: ninja -t compdb [-hx] target [targets]\n"
             "\n"
             "options:\n"
             "  -h     display this help message\n"
             "  -x     expand @rspfile style response file invocations\n");
      return 1;
    }
  }
  argv += optind;
  argc -= optind;

  if (argc == 0) {
    Error("compdb-targets expects the name of at least one target");
    printf("usage: ninja -t compdb [-hx] target [targets]\n"
           "\n"
           "options:\n"
           "  -h     display this help message\n"
           "  -x     expand @rspfile style response file invocations\n");
    return 1;
  }

  std::vector<Node*> nodes;
  std::string err;
  if (!CollectTargetsFromArgs(argc, argv, &nodes, &err)) {
    Fatal("%s", err.c_str());
  }

  std::set<Edge*> seen;
  std::vector<Edge*> edges;
  for (std::vector<Node*>::iterator n = nodes.begin(); n != nodes.end(); ++n)
    CollectCompdbEdges((*n)->in_edge(), &seen, &edges);

  std::vector<char> cwd;
  if (!GetCwd(&cwd))
    return 1;

  putchar('[');
  bool first = true;
  for (std::vector<Edge*>::iterator e = edges.begin(); e != edges.end(); ++e) {
    if ((*e)->inputs_.empty())
      continue;
    for (std::vector<Node*>::iterator in = (*e)->inputs_.begin();
         in != (*e)->inputs_.end(); ++in) {
      if (!first)
        putchar(',');
      printCompdb(&cwd[0], *e, *in, eval_mode);
      first = false;
    }
  }
  puts("\n]");
  return 0;
}

int NinjaMain::ToolRecompact(const Options* options, int argc, char* argv[]) {
  if (!EnsureBuildDirExists())
    return 1;

  if (OpenBuildLog(/*recompact_only=*/true) == LOAD_ERROR ||
      OpenDepsLog(/*recompact_only=*/true) == LOAD_ERROR)
    return 1;

  return 0;
}

int NinjaMain::ToolRestat(const Options* options, int argc, char* argv[]) {
  // The restat tool uses getopt, and expects argv[0] to contain the name of the
  // tool, i.e. "restat"
  argc++;
  argv--;

  optind = 1;
  int opt;
  while ((opt = getopt(argc, argv, const_cast<char*>("h"))) != -1) {
    switch (opt) {
    case 'h':
    default:
      printf("usage: ninja -t restat [outputs]\n");
      return 1;
    }
  }
  argv += optind;
  argc -= optind;

  if (!EnsureBuildDirExists())
    return 1;

  std::string log_path = ".ninja_log";
  if (!build_dir_.empty())
    log_path = build_dir_ + "/" + log_path;

  std::string err;
  const LoadStatus status = build_log_.Load(log_path, &err);
  if (status == LOAD_ERROR) {
    Error("loading build log %s: %s", log_path.c_str(), err.c_str());
    return EXIT_FAILURE;
  }
  if (status == LOAD_NOT_FOUND) {
    // Nothing to restat, ignore this
    return EXIT_SUCCESS;
  }
  if (!err.empty()) {
    // Hack: Load() can return a warning via err by returning LOAD_SUCCESS.
    Warning("%s", err.c_str());
    err.clear();
  }

  bool success = build_log_.Restat(log_path, disk_interface_, argc, argv, &err);
  if (!success) {
    Error("failed recompaction: %s", err.c_str());
    return EXIT_FAILURE;
  }

  if (!config_.dry_run) {
    if (!build_log_.OpenForWrite(log_path, *this, &err)) {
      Error("opening build log: %s", err.c_str());
      return EXIT_FAILURE;
    }
  }

  return EXIT_SUCCESS;
}

int NinjaMain::ToolUrtle(const Options* options, int argc, char** argv) {
