new = '''static bool ReadFileToString(const std::string& path, std::string* out) {
  std::ifstream f(path.c_str());
  if (!f)
    return false;
  std::string s((std::istreambuf_iterator<char>(f)),
                std::istreambuf_iterator<char>());
  *out = s;
  return true;
}

/// Parse "QUOTA PERIOD" (cgroup v2 cpu.max) or separate quota/period
/// values and return the CPU count limit, or 0 if there is none.
static int CpuLimitFromQuota(const std::string& quota_str,
                             const std::string& period_str) {
  if (quota_str.empty() || period_str.empty() || quota_str == "max")
    return 0;
  char* end;
  long long quota = strtoll(quota_str.c_str(), &end, 10);
  if (quota <= 0)
    return 0;
  long long period = strtoll(period_str.c_str(), &end, 10);
  if (period <= 0)
    return 0;
  long long cpus = (quota + period - 1) / period;  // round up
  if (cpus <= 0)
    return 0;
  if (cpus > 1000000)
    cpus = 1000000;
  return static_cast<int>(cpus);
}

static std::string Trim(const std::string& s) {
  size_t b = 0, e = s.size();
  while (b < e && (s[b] == ' ' || s[b] == '\\n' || s[b] == '\\t' || s[b] == '\\r'))
    ++b;
  while (e > b && (s[e - 1] == ' ' || s[e - 1] == '\\n' || s[e - 1] == '\\t' ||
                   s[e - 1] == '\\r'))
    --e;
  return s.substr(b, e - b);
}

static int CalculateProcessorCountFromCgroup() {
  // Determine our cgroup path(s) from /proc/self/cgroup.
  std::string v2_path, v1_cpu_path;
  std::string cgroup;
  if (ReadFileToString("/proc/self/cgroup", &cgroup)) {
    size_t pos = 0;
    while (pos < cgroup.size()) {
      size_t nl = cgroup.find('\\n', pos);
      if (nl == std::string::npos)
        nl = cgroup.size();
      std::string line = cgroup.substr(pos, nl - pos);
      pos = nl + 1;
      size_t c1 = line.find(':');
      if (c1 == std::string::npos)
        continue;
      size_t c2 = line.find(':', c1 + 1);
      if (c2 == std::string::npos)
        continue;
      std::string hierarchy = line.substr(0, c1);
      std::string controllers = line.substr(c1 + 1, c2 - c1 - 1);
      std::string path = line.substr(c2 + 1);
      if (hierarchy == "0" && controllers.empty()) {
        v2_path = path;
      } else {
        // cgroup v1: look for the cpu controller.
        size_t p = 0;
        while (p <= controllers.size()) {
          size_t comma = controllers.find(',', p);
          if (comma == std::string::npos)
            comma = controllers.size();
          if (controllers.substr(p, comma - p) == "cpu")
            v1_cpu_path = path;
          p = comma + 1;
        }
      }
    }
  }

  // cgroup v2: /sys/fs/cgroup<path>/cpu.max contains "$QUOTA $PERIOD".
  {
    std::string content;
    bool ok = false;
    if (!v2_path.empty())
      ok = ReadFileToString("/sys/fs/cgroup" + v2_path + "/cpu.max", &content);
    if (!ok)
      ok = ReadFileToString("/sys/fs/cgroup/cpu.max", &content);
    if (ok) {
      std::string s = Trim(content);
      size_t sp = s.find(' ');
      std::string quota = sp == std::string::npos ? s : s.substr(0, sp);
      std::string period = sp == std::string::npos ? "" : Trim(s.substr(sp + 1));
      int limit = CpuLimitFromQuota(quota, period);
      if (limit > 0)
        return limit;
      if (quota == "max")
        return 0;
    }
  }

  // cgroup v1: cpu.cfs_quota_us / cpu.cfs_period_us.
  {
    std::string quota, period;
    bool ok = false;
    if (!v1_cpu_path.empty())
      ok = ReadFileToString("/sys/fs/cgroup/cpu" + v1_cpu_path + "/cpu.cfs_quota_us", &quota) &&
           ReadFileToString("/sys/fs/cgroup/cpu" + v1_cpu_path + "/cpu.cfs_period_us", &period);
    if (!ok)
      ok = ReadFileToString("/sys/fs/cgroup/cpu/cpu.cfs_quota_us", &quota) &&
           ReadFileToString("/sys/fs/cgroup/cpu/cpu.cfs_period_us", &period);
    if (!ok)
      ok = ReadFileToString("/sys/fs/cgroup/cpu,cpuacct/cpu.cfs_quota_us", &quota) &&
           ReadFileToString("/sys/fs/cgroup/cpu,cpuacct/cpu.cfs_period_us", &period);
    if (ok)
      return CpuLimitFromQuota(Trim(quota), Trim(period));
  }
  return 0;
}

